<script setup lang="ts">const route=useRoute();const{request}=useApi();const assets=ref<any[]>([]);const loading=ref(true);const error=ref('');async function load(){try{assets.value=await request(`/campaigns/${route.params.id}/assets`)}catch(e){error.value=e instanceof Error?e.message:'We could not load campaign assets.'}finally{loading.value=false}}function updated(asset:any){assets.value=assets.value.map(x=>x.id===asset.id?asset:x)}onMounted(load)</script>
<template><section class="mx-auto max-w-5xl px-6 py-16"><h1 class="text-3xl font-bold">Campaign assets</h1><p v-if="loading" class="mt-6 text-cyan-300">Loading campaign assets…</p><p v-else-if="error" class="mt-6 rounded bg-red-950 p-3 text-red-200">{{error}}</p><p v-else-if="!assets.length" class="mt-6 rounded border border-dashed border-slate-700 p-8 text-slate-400">No assets yet. Generate campaign assets first.</p><div v-else class="mt-8 grid gap-5"><AssetCard v-for="asset in assets" :key="asset.id" :asset="asset" @updated="updated"/></div></section></template>
